1	/** 验收Driver工件的唯一落盘助手；命名与防覆盖仍由生产archive.ts实现。 */
2	import fs from 'node:fs';
3	import path from 'node:path';
4	import {writeArtifact} from '../../../../dist/test/src/trivium/archive.js';
5	import {readTask} from '../../../../dist/test/src/trivium/meta.js';
6	const config=JSON.parse(fs.readFileSync(import.meta.dirname+'/client-batch.json'));
7	if(process.cwd()!==config.fixture)throw Error('验收项目不符');
8	const input=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
9	// kind:null表示原稿；rerunIndex仍须是首轮1或后续正整数，不能填null。
10	if(!Number.isSafeInteger(input.rerunIndex)||input.rerunIndex<1)throw Error('rerunIndex须为正整数；首轮填1，kind:null仅表示原稿');
11	if(!config.topics.includes(input.topic)||!['plan','code','bug'].includes(input.stage))throw Error('主题/阶段不在本批');
12	const layout={archiveRoot:path.join(process.cwd(),'.reviews'),topic:input.topic};
13	const task=await readTask(layout),claimed=task?.drivers?.[input.stage]?.driver;
14	if(['plan','bug'].includes(input.stage)&&claimed!==input.driver)throw Error('先认领本阶段');
15	if(input.role!==input.driver)throw Error('只能产出本轮Driver工件');
16	// 跨日继续验收时由生产archive.ts的localDate命名，不固定为首日日期；旧件不改写。
17	console.log(JSON.stringify(await writeArtifact({layout,stage:input.stage,writer:'driver',driver:input.driver,role:input.role,kind:input.kind??null,rerunIndex:input.rerunIndex,content:input.content})));
